import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Button, Card, Form } from 'react-bootstrap';
import { Controller, useForm } from 'react-hook-form';
import { useDispatch, useSelector } from 'react-redux';
import { createScheduleAction } from '../../../redux/schedule/action';
import { decryptMessage, encryptMessage } from '../../../cryptoUtils';
import { getDoctorsAction } from '../../../redux/actions';
import Spinner from '../../../constants/Spinner';
import Select from 'react-select';

const AddHoliday = () => {
    const store = useSelector((state) => state);
    const navigate = useNavigate();
    const dispatch = useDispatch();
    const [status, setStatus] = useState(true);
    const [skip, setSkip] = useState(1);
    const [doctorSearch, setDoctorSearch] = useState('');
    const [selectedDoctor, setSelectedDoctor] = useState(null);
    const addResponse = store?.createScheduleReducer?.data?.response?.status;
    const doctorDetails = store?.getDoctorsReducer?.data?.result;
    const doctorOptions = doctorDetails?.map((data) => ({
        value: data._id,
        label: ((data?.name?.[0]?.prefix?.[0]
            ? data?.name?.[0]?.prefix?.[0] + ' '
            : '') +
            (data?.name?.[0]?.family || '') +
            (data?.name?.[0]?.given?.length > 0
                ? ' ' + data?.name?.[0]?.given?.join(' ')
                : '') || 'N/A') + ' (' + data?.userId?.email + ')',
    }));

    useEffect(() => {
        if (addResponse === 200) {
            reset();
            const payload = {
                search: doctorSearch,
                status: status,
                page: skip,
                limit: 10,
            };
            dispatch(getDoctorsAction(payload));
            navigate('/apps/schedule/list');
        }
    }, [addResponse, status, skip]);
    const {
        register,
        control,
        handleSubmit,
        reset,
        formState: { errors },
        watch,
    } = useForm();
    // const clinicId = JSON.parse(sessionStorage.getItem('hyper_user'))?.clinicId;
    const clinicId = decryptMessage(localStorage?.getItem('subClinicLocation')) || '';


    const onSubmit = (data) => {
        // const doctorInfo = JSON.parse(data.doctorInfo);
        const payload = {
            doctorId: selectedDoctor?.value,
            clinicId: clinicId,
            fromDate: data.fromDate,
            toDate: data.tillDate,
            // type: 'Holiday',
            // name: selectedDoctor?.label,
            reason: data?.reason,
        };
        dispatch(createScheduleAction({ key: encryptMessage(payload) }));
    };

    useEffect(() => {
        const payload = {
            search: doctorSearch,
            status: status,
            page: skip,
            limit: 10,
        };
        dispatch(getDoctorsAction(payload));
    }, [dispatch, doctorSearch, status, skip]);

    const handleInputChange = (data, type) => {
        if (type === 'doctor') {
            setDoctorSearch(data);
        }
    };

    const handleChange = (selectedOption, type) => {
        // setSelectedPatient(selectedOption, 'Selected Option');
        if (type === 'doctor') {
            setSelectedDoctor(selectedOption, 'Selected Option');
        }
    };
    return (
        <div className="background_Color ">
            <div className="container-fluid mt-2  px-0">
                <Card className="px-md-3 py-md-2" style={{ height: '85vh' }}>
                    <div className="d-flex justify-content-between">
                        <p style={{ fontWeight: 600 }}>ADD HOLIDAY</p>
                        <div>
                            <Button className="cancel-button" onClick={() => navigate('/apps/schedule/list')}>
                                Back
                            </Button>
                        </div>
                    </div>

                    <div className="px-">
                        {store?.getDoctorsReducer?.loading ? (
                            <div className="d-flex justify-content-center align-items-center h-100">
                                <Spinner />
                            </div>
                        ) : (
                            <Form onSubmit={handleSubmit(onSubmit)}>
                                <div className="row pb-2 mt-1">
                                    <div className="col-md-6 col-sm-6 col-12">
                                        <Form.Group className="mb-1 responnsible-party-select">
                                            <Form.Label className="mb-0">
                                                Provider Name<span className="text-danger">*</span>
                                            </Form.Label>
                                            <Controller
                                                name="doctor"
                                                control={control}
                                                rules={{ required: 'Please select the provider' }}
                                                render={({ field }) => (
                                                    <Select
                                                        {...field}
                                                        classNamePrefix="select"
                                                        isLoading={store?.getDoctorsReducer?.loading}
                                                        isClearable={true}
                                                        isSearchable={true}
                                                        options={doctorOptions}
                                                        onChange={(val) => {
                                                            field.onChange(val);
                                                            setSelectedDoctor(val); // update local state if needed
                                                        }}
                                                        onInputChange={(inputValue) =>
                                                            handleInputChange(inputValue, 'doctor')
                                                        }
                                                        placeholder="Select Provider Name"
                                                    />
                                                )}
                                            />
                                            {errors.doctor && (
                                                <span className="text-danger">{errors.doctor.message}</span>
                                            )}
                                        </Form.Group>

                                        <Form.Group className="mb-1">
                                            <Form.Label className="mb-0">
                                                Till Date<span className="text-danger">*</span>
                                            </Form.Label>
                                            <Form.Control
                                                type="date"
                                                {...register('tillDate', {
                                                    required: 'Till date is required',
                                                    validate: (value) => {
                                                        const fromDate = watch('fromDate');
                                                        if (!fromDate) return true; // skip check if fromDate not filled yet
                                                        return (
                                                            new Date(value) >= new Date(fromDate) ||
                                                            'Till date must be after From date'
                                                        );
                                                    },
                                                })}
                                            />
                                            {errors.tillDate && (
                                                <small className="text-danger">{errors.tillDate.message}</small>
                                            )}
                                        </Form.Group>
                                    </div>

                                    <div className="col-md-6 col-sm-6 col-12">
                                        <Form.Group className="mb-1">
                                            <Form.Label className="mb-0">
                                                From Date<span className="text-danger">*</span>
                                            </Form.Label>
                                            <Form.Control
                                                type="date"
                                                {...register('fromDate', {
                                                    required: 'From date is required',
                                                    validate: (value) => {
                                                        const tillDate = watch('tillDate');
                                                        if (!tillDate) return true;
                                                        return (
                                                            new Date(value) <= new Date(tillDate) ||
                                                            'From date must be before Till date'
                                                        );
                                                    },
                                                })}
                                            />
                                            {errors.fromDate && (
                                                <small className="text-danger">{errors.fromDate.message}</small>
                                            )}
                                        </Form.Group>

                                        <Form.Group className="mb-1">
                                            <Form.Label className="mb-0">
                                                Reason<span className="text-danger">*</span>
                                            </Form.Label>
                                            <Form.Control
                                                as="textarea"
                                                rows={3}
                                                {...register('reason', {
                                                    required: 'Reason is required',
                                                })}
                                            />
                                            {errors.reason && (
                                                <small className="text-danger">{errors.reason.message}</small>
                                            )}
                                        </Form.Group>
                                    </div>
                                </div>

                                <div className="d-flex gap-2 justify-content-end mb-2">
                                    <Button className="cancel-button" type="button" onClick={() => navigate(-1)}>
                                        Cancel
                                    </Button>
                                    <Button
                                        className="custom-buttons"
                                        disabled={store?.createScheduleReducer?.loading}
                                        type="submit"
                                        style={{ width: '55px' }}>
                                        {store?.createScheduleReducer?.loading ? (
                                            <Spinner className="spinner-border-sm" color="white" />
                                        ) : (
                                            'Save'
                                        )}
                                    </Button>
                                </div>
                            </Form>
                        )}
                    </div>
                </Card>
            </div>
        </div>
    );
};

export default AddHoliday;
